{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 3,
      "verse": 8,
      "source_ref": "3:8",
      "text_ar": "وكان روح الله على أخنوخ، فكان يعلِّم جميع رجاله حكمة الله وطرقه، وكان أبناء البشر يعبدون الرب طوال أيام أخنوخ، فكانوا يأتون لسماع حكمته."
    },
    {
      "chapter": 3,
      "verse": 9,
      "source_ref": "3:9",
      "text_ar": "وكان جميع ملوك أبناء البشر، الأول والآخر، مع أمرائهم وقضاتهم، يأتون إلى أخنوخ عندما سمعوا بحكمته، فكانوا يركعون له، وطلبوا من أخنوخ أن يحكمهم، فوافق على ذلك."
    },
    {
      "chapter": 3,
      "verse": 10,
      "source_ref": "3:10",
      "text_ar": "وتجمعوا جميعًا، مائة وثلاثون ملكًا وأميرًا، فجعلوا أخنوخ ملكًا عليهم وكانوا جميعًا تحت سلطته وأمره."
    },
    {
      "chapter": 3,
      "verse": 11,
      "source_ref": "3:11",
      "text_ar": "وعلَّمهم أخنوخ الحكمة والعلم وطرقات الرب؛ فصنع بينهم سلامًا، وكان السلام سائدًا في الأرض طوال حياة أخنوخ."
    },
    {
      "chapter": 3,
      "verse": 12,
      "source_ref": "3:12",
      "text_ar": "وحكم أخنوخ على أبناء البشر مدة مئتي وثلاثة وأربعين سنة، فكان يطبق العدل والبر مع جميع قومه، ويقودهم إلى سبل الرب."
    },
    {
      "chapter": 3,
      "verse": 13,
      "source_ref": "3:13",
      "text_ar": "وهذه أجيال أخنوخ، متوشالح، وإليشع، وإليملخ، ثلاثة أبناء؛ وكانت أخواتهم ملقة وناما، وعاش متوشالح سبعًا وثمانين سنة وأنجب لاميك."
    },
    {
      "chapter": 3,
      "verse": 14,
      "source_ref": "3:14",
      "text_ar": "وكان ذلك في السنة السادسة والخمسين من حياة لاميك حين مات آدم؛ كان عمره تسعمائة وثلاثين سنة عند وفاته، فدفنه ابناه مع أخنوخ ومتوشالح ابنه، بطقوسٍ عظيمة كما في دفن الملوك، في الكهف الذي أخبره الله به."
    },
    {
      "chapter": 3,
      "verse": 15,
      "source_ref": "3:15",
      "text_ar": "وفي ذلك المكان أبى جميع أبناء البشر حزنًا كبيرًا وبكاءً على آدم؛ فصار ذلك عادةً عند أبناء البشر إلى اليوم."
    },
    {
      "chapter": 3,
      "verse": 16,
      "source_ref": "3:16",
      "text_ar": "مات آدم لأنه أكل من شجرة المعرفة؛ هو وذريته من بعده، كما قال ربّ الله."
    },
    {
      "chapter": 3,
      "verse": 17,
      "source_ref": "3:17",
      "text_ar": "وكان ذلك في سنة وفاة آدم، وهي السنة المئتين والثلاثة والأربعين من حكم أخنوخ؛ فقرر أخنوخ في ذلك الوقت أن ينفصل عن أبناء البشر ويختفي كما كان في البداية ليخدم الرب."
    }
  ]
}
